import java.util.Arrays;
class LibraryMember {protected int borrowed;private int[] history=new int[10];private int n;public LibraryMember(String id,int limit){if(id==null||id.trim().length()<4||limit<=0)throw new IllegalArgumentException();}protected void chargeFine(int a){if(n>=10||a<=0)throw new IllegalArgumentException();history[n++]=a;}public int[] getFineHistory(){return Arrays.copyOf(history,n);}public int getTotalFine(){return Arrays.stream(history,0,n).sum();}public void borrowBook(){borrowed++;}public int getBooksBorrowed(){return borrowed;}public String displayInfo(){return "General | Books: "+borrowed;}}
class StudentMember extends LibraryMember {String course;public StudentMember(String id,int limit,String c){super(id,limit);course=c;}@Override protected void chargeFine(int a){super.chargeFine(a/2);}@Override public String displayInfo(){return "Student | Course: "+course+" | Books: "+borrowed;}}
public class Problem3_StudentDiscountFineLedger {public static void main(String[]x){StudentMember s=new StudentMember("STU5",3,"CSE");s.chargeFine(100);int[] h=s.getFineHistory();h[0]=999;System.out.println(s.getTotalFine()+" "+Arrays.toString(s.getFineHistory()));}}